static const schema::ClassSchema& replicator() {
    const schema::ClassSchema* s = gen::find_class_schema("ANodeLayoutReplicator");
    if (!s) {
        std::printf("  [FAIL] no schema ANodeLayoutReplicator\n");
        std::exit(2);
    }
    return *s;
}

static std::vector<uint8_t> bytes_of_hex(const char* hex) {
    auto nib = [](char c) { return c <= '9' ? c - '0' : c - 'a' + 10; };
    std::vector<uint8_t> out;
    for (size_t i = 0; hex[i] && hex[i + 1]; i += 2) out.push_back(static_cast<uint8_t>(nib(hex[i]) << 4 | nib(hex[i + 1])));
    return out;
}

static bool same_bits(const emit::BunchWriter& w, const std::vector<uint8_t>& want, size_t bits) {
    if (w.bit_pos() != bits) return false;
    for (size_t i = 0; i < bits; ++i) {
        if (((w.bytes()[i >> 3] >> (i & 7)) & 1) != ((want[i >> 3] >> (i & 7)) & 1)) return false;
    }
    return true;
}

