/// The items retail has beyond the node's layout and its pre-built plots, per (node, level, season): the service buildings a mayor built and the expansions bought
/// (research/spike_replicator/derived_run.txt "other").
static size_t extras_expected(int64_t node, int level, int season) {
    (void)season;
    switch (level) {
        case 4: return node == 6064633652044300331ll ? 13 : node == kJoeva ? 12 : node == kWinstead ? 13 : 0;   // (KalTorhum shows the Large project too: 19 plot items)
        case 3: return node == kHalcyon ? 6 : 6;   // Wildport, Vexhelm, Halcyon and Aithanahr: 6 each
        default: return 0;
    }
}

/// Where two item lists first differ (empty when they do not): for the failure message.
static std::string first_diff(const std::vector<repl::NodeLayoutItem>& a, const std::vector<repl::NodeLayoutItem>& b) {
    char buf[400];
    for (size_t i = 0; i < std::min(a.size(), b.size()); ++i) {
        if (a[i] == b[i]) continue;
        const auto& x = a[i];
        const auto& y = b[i];
        std::snprintf(buf, sizeof buf, "item %zu: ours owner %lld/%d/%d set %lld t(%g,%g,%g) vs retail owner %lld/%d/%d set %lld t(%g,%g,%g)", i, static_cast<long long>(x.owner_guid), x.owner_secondary,
                      x.owner_index, static_cast<long long>(x.asset_set), x.translation.x, x.translation.y, x.translation.z, static_cast<long long>(y.owner_guid), y.owner_secondary, y.owner_index,
                      static_cast<long long>(y.asset_set), y.translation.x, y.translation.y, y.translation.z);
        return buf;
    }
    if (a.size() != b.size()) {
        std::snprintf(buf, sizeof buf, "%zu items against %zu", a.size(), b.size());
        return buf;
    }
    return "";
}

static void test_items() {
    std::printf("the items against the 18 retail payloads\n");
    size_t no_extras = 0, bits_equal = 0, cases = 0, plot_order_differs = 0;
    for (const capture_node_layout::Case& c : capture_node_layout::kCases) {
        ++cases;
        const std::string what = std::string(c.source) + " (node " + std::to_string(c.node) + ", level " + std::to_string(c.level) + ", season " + std::to_string(c.season) + ")";
        const std::vector<uint8_t> raw = bytes_of_hex(c.hex);
        const auto retail = repl::read_node_layout_payload(replicator(), raw.data(), c.bits);
        const world::CityNodeInfo* info = g_nodes->by_guid(c.node);
        CHECK(retail && info, (what + ": the payload reads and the node is one of the registry's").c_str());
        if (!retail || !info) continue;
        const int64_t layout = g_wire->layout_of(c.node);
        const auto& plots = g_wire->plot_rows(layout, c.level);
        std::set<int64_t> prebuilt;
        std::map<int64_t, uint8_t> states;
        for (const world::PlotRow& r : plots) {
            if (!r.pre_construct) continue;
            prebuilt.insert(r.plot);
            uint8_t state = 0;   // a plot retail shows nothing on stays out
            for (const auto& e : retail->items) {
                if (e.item.owner_guid == r.plot) state = static_cast<uint8_t>(e.item.owner_secondary);
            }
            states[r.plot] = state;
        }
        world::LayoutRequest req;
        req.node = c.node;
        req.context.level = c.level;
        req.context.culture = c.culture;
        req.context.node_type = info->type;
        req.context.season = c.season;
        const world::CityZoneInfo* zone = g_nodes->zone_by_guid(info->zoi_guid);
        req.context.biome = zone ? zone->biome : -1;
        req.plot_states = &states;
        const std::vector<repl::NodeLayoutItem> mine = g_data->items(*g_wire, req);
// [C-O-A - C.Y.B]

        // retail's items split: the node's layout, the pre-built plots', the rest
        std::vector<repl::NodeLayoutItem> r_layout, r_plots;
        size_t extras = 0;
        for (const auto& e : retail->items) {
            if (e.item.owner_guid == c.node) r_layout.push_back(e.item);
            else if (prebuilt.count(e.item.owner_guid)) r_plots.push_back(e.item);
            else ++extras;
        }
        std::vector<repl::NodeLayoutItem> m_layout, m_plots;
        for (const auto& it : mine) (it.owner_guid == c.node ? m_layout : m_plots).push_back(it);
        CHECKF(m_layout == r_layout, "%s: the %zu layout items are retail's (%zu built), same indices, asset sets and transforms to the last bit [%s]", what.c_str(), r_layout.size(), m_layout.size(),
               first_diff(m_layout, r_layout).c_str());
        // the plots' items are retail's; their ORDER is the server's history (a plot rebuilt moves in its list: Aithanahr's plot 22 comes first), so it is compared as a set and
        // the order of the layout's plots is counted
        const auto same_set = [](std::vector<repl::NodeLayoutItem> a, std::vector<repl::NodeLayoutItem> b) {
            const auto key = [](const repl::NodeLayoutItem& x) { return std::make_tuple(x.owner_guid, x.owner_secondary, x.owner_index); };
            const auto less = [&](const repl::NodeLayoutItem& x, const repl::NodeLayoutItem& y) { return key(x) < key(y); };
            std::sort(a.begin(), a.end(), less);
            std::sort(b.begin(), b.end(), less);
            return a == b;
        };
        const bool plots_set = same_set(m_plots, r_plots);
        CHECKF(plots_set, "%s: the %zu items of the pre-built plots are retail's (%zu built) [%s]", what.c_str(), r_plots.size(), m_plots.size(), first_diff(m_plots, r_plots).c_str());
        if (plots_set && m_plots != r_plots) ++plot_order_differs;
        CHECKF(extras == extras_expected(c.node, c.level, c.season), "%s: retail has %zu items beyond them (built service buildings and expansions; expected %zu)", what.c_str(), extras,
               extras_expected(c.node, c.level, c.season));

        // the exact bits: retail's header and ids with our derivable items where retail has them and retail's own for the rest
        repl::NodeLayoutPayload merged = *retail;
        size_t li = 0;
        for (auto& e : merged.items) {
            if (e.item.owner_guid == c.node) {
                if (li < m_layout.size()) e.item = m_layout[li++];
            } else if (prebuilt.count(e.item.owner_guid)) {   // ours by identity: retail's order of the plots
                for (const auto& mine_item : m_plots) {
                    if (mine_item.owner_guid == e.item.owner_guid && mine_item.owner_secondary == e.item.owner_secondary && mine_item.owner_index == e.item.owner_index) {
                        e.item = mine_item;
                        break;
                    }
                }
            }
        }
        emit::BunchWriter w;
        const size_t bits = repl::write_node_layout_snapshot(replicator(), merged, w);
        const bool exact = bits == c.bits && same_bits(w, raw, c.bits);
        CHECKF(exact, "%s: written with retail's header and ids, our items and retail's other %zu are the exact bits of the capture", what.c_str(), extras);
        bits_equal += exact ? 1 : 0;
        no_extras += extras == 0 ? 1 : 0;
        // when retail has nothing beyond the derivable, the whole payload's items are ours
        if (extras == 0) {
            std::vector<repl::NodeLayoutItem> retail_items;
            for (const auto& e : retail->items) retail_items.push_back(e.item);
            CHECKF(same_set(mine, retail_items), "%s: and the whole item list is ours", what.c_str());
        }
    }
    CHECK(cases == 18 && bits_equal == 18, "all 18 cases reproduce to the exact bits");
    CHECKF(plot_order_differs <= 1, "the plots come in the layout's order in 17 of the 18 payloads (%zu differ: Aithanahr's)", plot_order_differs);
    CHECK(no_extras >= 9, "nine of the cases are whole payloads from the data alone (the harbours, Hecribba and Azmaran)");
}

/// The default start: every pre-built plot Operational.
static std::vector<repl::NodeLayoutItem> default_items(int64_t node, int level, int season = world::kSpring) {
    const world::CityNodeInfo* info = g_nodes->by_guid(node);
    world::LayoutRequest req;
    req.node = node;
    req.context.level = level;
    req.context.node_type = info->type;
    req.context.season = season;
    const world::CityZoneInfo* zone = g_nodes->zone_by_guid(info->zoi_guid);
    req.context.biome = zone ? zone->biome : -1;
    return g_data->items(*g_wire, req);
}

static size_t count_owner(const std::vector<repl::NodeLayoutItem>& items, int64_t node, bool layout) {
    size_t n = 0;
    for (const auto& it : items) n += ((it.owner_guid == node) == layout) ? 1 : 0;
    return n;
}
// ~ C Y B - CoA ~

static void test_defaults() {
    std::printf("the default start\n");
    const auto joeva = default_items(kJoeva, 4);
    CHECKF(joeva.size() == 73 && count_owner(joeva, kJoeva, true) == 55 && count_owner(joeva, kJoeva, false) == 18, "Joeva at Town: %zu items = %zu layout + %zu plot (73 = 55 + 18)",
           joeva.size(), count_owner(joeva, kJoeva, true), count_owner(joeva, kJoeva, false));
    const auto halcyon = default_items(kHalcyon, 3);
    CHECKF(halcyon.size() == 61 && count_owner(halcyon, kHalcyon, true) == 45 && count_owner(halcyon, kHalcyon, false) == 16, "Halcyon at Village: %zu items = %zu layout + %zu plot (61 = 45 + 16)",
           halcyon.size(), count_owner(halcyon, kHalcyon, true), count_owner(halcyon, kHalcyon, false));
    const auto winstead = default_items(kWinstead, 4);
    CHECKF(winstead.size() == 73, "Winstead at Town: %zu items (73)", winstead.size());
    bool all_operational = true;
    for (const auto& it : joeva) all_operational = all_operational && (it.owner_guid == kJoeva ? it.owner_secondary == 0 : it.owner_secondary == 2);
    CHECK(all_operational, "every plot item of the start is Operational (2), every layout item has secondary id 0");
    // the numbers of bits the spike derived
    repl::NodeLayoutHeader h;
    h.level = 4;
    h.season = 2;
    h.tags = {repl::kSiegeInactiveTag};
    h.plot_version = 1;
    repl::FastArrays arrays;
    CHECK(repl::sync_node_layout(replicator(), arrays, h, joeva), "Joeva's items sync");
    const auto st = repl::read_node_layout_state(replicator(), arrays);
    emit::BunchWriter w;
    CHECK(st && repl::write_node_layout_snapshot(replicator(), *st, w) == 58881, "Joeva's payload is 58,881 bits (the spike's number)");
    // a level the layout holds nothing at
    CHECK(default_items(kJoeva, 0).size() < joeva.size(), "a lower level draws less");
    CHECK(default_items(6064630651307950121ll, 4).empty(), "a record that is no real node (Lionhold's) has no items");
    // the season only matters through the definition filter: Winter and Summer give the same counts at Joeva
    CHECK(default_items(kJoeva, 4, world::kWinter).size() == joeva.size() && default_items(kJoeva, 4, world::kSummer).size() == joeva.size(), "the season changes nothing at Joeva (Winter, Spring, Summer)");
    // the biome filter is real: asked for a biome of the wrong region the town loses items
    world::LayoutRequest req;
    req.node = kJoeva;
    req.context.level = 4;
    req.context.node_type = g_nodes->by_guid(kJoeva)->type;
    req.context.biome = 11;   // Jungle
    CHECK(g_data->items(*g_wire, req) != joeva, "Joeva in the wrong biome draws something else");
    // the data policy: the NodeXP projects as the design data starts them
    req.context.biome = g_nodes->zone_by_guid(g_nodes->by_guid(kJoeva)->zoi_guid)->biome;
    req.plots = world::PlotPolicy::DataStartingState;
    const auto data_items = g_data->items(*g_wire, req);
    size_t under_construction = 0;
    for (const auto& it : data_items) under_construction += it.owner_secondary == 1 ? 1 : 0;
    CHECK(under_construction > 0 && data_items.size() == 73, "the data's own start has the NodeXP projects under construction (1)");
}

