namespace {
// (C.O.A + C:Y:B)

const conn::OuterHeader kOuter{0x500c7696u, 0, 5};
const conn::CustomField kCf{0x38, 0x21, 0xc7, 0x0d, 0x43, 0x5d};
const Clock::time_point t0{seconds(1000)};

ConnectionConfig server_config() {
    ConnectionConfig c;
    c.outer = kOuter;
    c.custom_field = kCf;
    c.server_initial_seq = 14265;
    c.client_initial_seq = 15870;
    return c;
}

ConnectionConfig client_config() {
    ConnectionConfig c = server_config();
    std::swap(c.server_initial_seq, c.client_initial_seq);
    return c;
}

struct Seen {
    uint32_t channel;
    bool     open, close, reliable;
    uint32_t reason;
    size_t   bits;
};

struct Pair {
    Connection s{server_config(), t0};
    Connection cl{client_config(), t0};
    Clock::time_point t = t0;
    std::vector<Seen> seen;

    void step(ActorView* view, milliseconds dt = milliseconds(60)) {
        t += dt;
        for (const auto& p : s.flush(t)) {
            for (auto& b : cl.receive(p, t)) {
                if (b.channel == 0) continue;
                seen.push_back({b.channel, b.open, b.close, b.reliable, b.close_reason, b.bits});
            }
        }
        t += dt;
        for (const auto& p : cl.flush(t)) s.receive(p, t);
        for (const AckEvent& e : s.take_ack_events()) {
            if (view) view->on_ack(e);
        }
    }
};

std::function<bool(uint32_t)> reserved_3_to_6() { return [](uint32_t i) { return i >= 3 && i <= 6; }; }

void run(ActorView& v, Pair& p, double x, double y, int steps = 1) {
    for (int i = 0; i < steps; ++i) {
        v.tick(p.s, x, y, p.t);
        p.step(&v, milliseconds(65));
    }
}

std::vector<Seen> take(Pair& p) {
    std::vector<Seen> out;
    out.swap(p.seen);
    return out;
}

size_t bits_on(const std::vector<Seen>& seen, uint32_t channel, bool* closed = nullptr, uint32_t* reason = nullptr) {
    size_t n = 0;
    for (const Seen& x : seen) {
        if (x.channel != channel) continue;
        n += x.bits;
        if (x.close) {
            if (closed) *closed = true;
            if (reason) *reason = x.reason;
        }
    }
    return n;
}
// built by C O A with Cyb

}  // namespace

static void test_view() {
    std::printf("the view: a player walks up to Joeva\n");
    Scene s;
    s.scenery->start();
    const world::WorldActor* joeva = s.actor_of(kJoeva);
    if (!joeva) {
        CHECK(false, "Joeva has a replicator");
        return;
    }
    const uint64_t id = joeva->id;
    const double jx = joeva->x, jy = joeva->y;
    Pair p;
    ActorView v(s.registry, ActorView::Config{}, reserved_3_to_6());
    // 1.6 km out: nothing
    run(v, p, jx + 160000, jy, 4);
    CHECK(v.state_of(id) == world::ClientState::None && take(p).empty(), "at 1.6 km Joeva's replicator is not sent");
    // 1.4 km: opened awake, on the first free channel, with the whole payload
    run(v, p, jx + 140000, jy, 12);
    CHECK(v.state_of(id) == world::ClientState::Awake && v.channel_of(id) == 7, "at 1.4 km it is open, awake, on channel 7 (3-6 are the session's own)");
    auto seen = take(p);
    const size_t open_bits = bits_on(seen, 7);
    CHECKF(open_bits >= 58881 && open_bits < 58881 + 6000, "the open carries the whole payload (58,881 bits) and the actor's header and exports (%zu bits on the channel)", open_bits);
    CHECK(v.stats().opens == 1 && v.stats().snapshots == 0, "an awake open, never a snapshot (the replicator is never dormant)");
    // staying: nothing more is sent
    run(v, p, jx + 140000, jy, 15);
    CHECK(take(p).empty(), "while the player stays nothing is sent");
    // hysteresis: 1.455 km stays open (the 10 m past the edge), 1.47 km closes with a Relevancy close
    run(v, p, jx + 145500, jy, 3);
    CHECK(v.state_of(id) == world::ClientState::Awake, "10 m past the edge it stays open");
    run(v, p, jx + 147000, jy, 3);
    seen = take(p);
    bool closed = false;
    uint32_t reason = 0;
    bits_on(seen, 7, &closed, &reason);
    CHECK(closed && reason == kCloseRelevancy && v.state_of(id) == world::ClientState::None, "beyond it is closed with a Relevancy close (the client destroys the actor)");
    // and back
    run(v, p, jx + 120000, jy, 8);
    CHECK(v.state_of(id) == world::ClientState::Awake, "walking back opens it again");
    take(p);

    // a level change while it is open: one update on the same channel, reliable, the whole new payload
    const uint32_t channel = v.channel_of(id);
    const size_t updates = v.stats().updates;
    s.set_level(kJoeva, 3);
    s.scenery->tick();
    run(v, p, jx + 120000, jy, 8);
    seen = take(p);
    size_t update_bits = 0;
    bool reliable = true, any_open = false;
    for (const Seen& x : seen) {
        if (x.channel != channel) continue;
        update_bits += x.bits;
        reliable = reliable && x.reliable;
        any_open = any_open || x.open;
    }
    CHECK(v.stats().updates == updates + 1 && update_bits > 0 && !any_open && reliable, "the level change is one reliable update on the replicator's channel (no new open)");
    const size_t want = default_items(kJoeva, 3).size();
    CHECKF(update_bits >= want * 800 && update_bits < want * 800 + 73 * 32 + 3000, "it carries the new list in full (%zu items) and deletes the old IDs (%zu bits)", want, update_bits);
    CHECK(v.channel_of(id) == channel && v.state_of(id) == world::ClientState::Awake, "the replicator stays open");
    run(v, p, jx + 120000, jy, 6);
    CHECK(take(p).empty(), "and nothing more follows");

    // a second player gets the same, from its own connection
    Pair p2;
    ActorView v2(s.registry, ActorView::Config{}, reserved_3_to_6());
    run(v2, p2, jx - 100000, jy, 12);
    CHECK(v2.state_of(id) == world::ClientState::Awake, "a second player 1 km away has it open too");
    const size_t second_bits = bits_on(take(p2), v2.channel_of(id));
    CHECKF(second_bits >= 49281 && second_bits < 49281 + 6000, "with the Village payload (61 items, 49,281 bits): %zu bits", second_bits);
    s.set_level(kJoeva, 4);
    s.scenery->tick();
    run(v, p, jx + 120000, jy, 8);
    run(v2, p2, jx - 100000, jy, 8);
    CHECK(v.stats().updates == updates + 2 && v2.stats().updates == 1, "the next level change reaches both");
    take(p);
    take(p2);
}
// (C O A ~ C Y B)

static void test_reach() {
    std::printf("the view: a player far from the towns\n");
    Scene s;
    const size_t n = s.scenery->start();
    Pair p;
    ActorView v(s.registry, ActorView::Config{}, reserved_3_to_6());
    run(v, p, 0, 0, 40);
    size_t open = 0;
    s.registry.for_each([&](const world::WorldActor& a) { open += v.state_of(a.id) == world::ClientState::Awake ? 1 : 0; });
    CHECKF(open <= n, "a player at the world's origin has only the replicators within 1.45 km (%zu of %zu)", open, n);
    const world::WorldActor* joeva = s.actor_of(kJoeva);
    const world::WorldActor* winstead = s.actor_of(kWinstead);
    if (joeva && winstead) {
        const double mx = (joeva->x + winstead->x) / 2, my = (joeva->y + winstead->y) / 2;
        const double d = std::hypot(joeva->x - winstead->x, joeva->y - winstead->y);
        Pair q;
        ActorView w(s.registry, ActorView::Config{}, reserved_3_to_6());
        run(w, q, mx, my, 60);
        const bool both = w.state_of(joeva->id) == world::ClientState::Awake && w.state_of(winstead->id) == world::ClientState::Awake;
        CHECKF(d / 2 > 145000.0 || both, "between Joeva and Winstead (%.0f m apart) the player has the replicators in range", d / 100.0);
    }
}

