static void test_world() {
    std::printf("the world: start_scenery and tick_world\n");
    const fs::path dir = cf::make_temp_dir("worldd_node_layout_");
    const fs::path db = dir / "content.db";
    if (!cf::make_db(db)) std::exit(2);
    std::string error;
    auto content = content::ContentDb::open(db.string(), error);
    if (!content) {
        std::printf("  [FAIL] the content.db does not open: %s\n", error.c_str());
        std::exit(2);
    }
    {
        aoc::protocol::ServerGuidAllocator guids{kServerId, kRandomizer};
        PlayerWorld world(&*content, "", bootstrap::GameStateMode::Tier3, kServerId, guids);
        auto nodes = world::CityNodes::load(db_path(), error);
        nodes->apply_seed_file(NODES_SEED_PATH, error);
        world::NodeScenery::Config cfg;
        CHECK(world.start_scenery(cfg) == 0 && world.scenery() == nullptr, "without nodes, a node wire and the layout data there is no scenery");
        world.set_city_nodes(nodes.get());
        world.set_node_wire(g_wire.get());
        CHECK(world.start_scenery(cfg) == 0, "...still none without the layout data");
        world.set_node_layout_data(g_data.get());
        world::NodeScenery::Config off;
        off.enabled = false;
        CHECK(world.start_scenery(off) == 0 && world.scenery() == nullptr, "disabled: none");
        const size_t n = world.start_scenery(cfg);
        CHECK(n >= 2 && world.scenery() && world.registry().count(world::ActorKind::NodeLayout) == n, "start_scenery makes the replicators in the world's registry");
        CHECK(world.start_scenery(cfg) == 0, "once");
        world::LiveNode ln;
        ln.guid = kJoeva;
        ln.level = 2;
        nodes->apply_change(ln);
        CHECK(world.scenery()->rebuilds() == 0, "a level change is not followed until the world ticks");
        world.tick_world(10.0);
        const auto* e = world.scenery()->entry_of(kJoeva);
        CHECK(world.scenery()->rebuilds() == 1 && e && e->level == 2 && e->plot_version == 2, "tick_world follows the node: Joeva rebuilt at level 2, PlotChangeVersion 2");
        world.tick_world(10.1);
        CHECK(world.scenery()->rebuilds() == 1, "and only once");
    }
    std::error_code ec;
    fs::remove_all(dir, ec);
}

int main() {
    spdlog::set_level(std::getenv("AOC_TEST_LOG") ? spdlog::level::debug : spdlog::level::off);
    std::string error;
    g_nodes = world::CityNodes::load(db_path(), error);
    if (!g_nodes) {
        std::printf("  [FAIL] the real content.db has no city nodes (%s): %s\n", db_path().c_str(), error.c_str());
        return 2;
    }
    g_wire = world::NodeWire::load(db_path(), *g_nodes, error);
    if (!g_wire) {
        std::printf("  [FAIL] the node wire does not load (%s): %s\n", db_path().c_str(), error.c_str());
        return 2;
    }
    g_data = world::NodeLayoutData::load(db_path(), error);
    if (!g_data) {
        std::printf("  [FAIL] the layout data does not load (%s): %s\n", db_path().c_str(), error.c_str());
        return 2;
    }
    test_items();
    test_defaults();
    test_scenery();
    test_level_change();
    test_view();
    test_reach();
    test_world();
    std::printf("\n%d passed, %d failed\n", g_pass, g_fail);
    return g_fail == 0 ? 0 : 1;
}
